class Solution {
public:
    vector<int> maximumLengthOfRanges(vector<int>& nums) {
        int n = nums.size();
        vector<int> left(n, -1), right(n, n);
        vector<int> st;
        for (int i = 0; i < n; ++i) {
            while (!st.empty() && nums[st.back()] < nums[i]) st.pop_back();
            if (!st.empty()) left[i] = st.back();
            st.push_back(i);
        }
        st.clear();
        for (int i = n - 1; i >= 0; --i) {
            while (!st.empty() && nums[st.back()] < nums[i]) st.pop_back();
            if (!st.empty()) right[i] = st.back();
            st.push_back(i);
        }
        vector<int> ans(n);
        for (int i = 0; i < n; ++i) ans[i] = right[i] - left[i] - 1;
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] maximumLengthOfRanges(int[] nums) {
        int n = nums.length;
        int[] left = new int[n];
        Arrays.fill(left, -1);
        int[] right = new int[n];
        Arrays.fill(right, n);
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[stack.peek()] < nums[i]) stack.pop();
            if (!stack.isEmpty()) left[i] = stack.peek();
            stack.push(i);
        }
        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && nums[stack.peek()] < nums[i]) stack.pop();
            if (!stack.isEmpty()) right[i] = stack.peek();
            stack.push(i);
        }
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) ans[i] = right[i] - left[i] - 1;
        return ans;
    }
}

