var maximumLengthOfRanges = function(nums) {
    const n = nums.length;
    const left = new Array(n).fill(-1);
    const right = new Array(n).fill(n);
    const stack = [];
    for (let i = 0; i < n; i++) {
        while (stack.length > 0 && nums[stack[stack.length - 1]] < nums[i]) stack.pop();
        if (stack.length > 0) left[i] = stack[stack.length - 1];
        stack.push(i);
    }
    stack.length = 0;
    for (let i = n - 1; i >= 0; i--) {
        while (stack.length > 0 && nums[stack[stack.length - 1]] < nums[i]) stack.pop();
        if (stack.length > 0) right[i] = stack[stack.length - 1];
        stack.push(i);
    }
    return nums.map((_, i) => right[i] - left[i] - 1);
};
